"""Authored V4 lessons. Helpers serialize reviewed rows; they never multiply examples."""
import json,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
rows=[]
def p(u,id,term,pt,en,code,out,a,b,definition,en_definition,focus,en_focus,patch=None,build=None,reading=None,error=None):
    rows.append(dict(unit=u,id='v4-'+id,term=term,title=pt,en_title=en,code=code,output=out,wrong=[a,b],definition=definition,en_definition=en_definition,focus=focus,en_focus=en_focus,patch=patch,build=build,reading=reading,error=error))
# Unit 1: names and output are taught by the preserved first two missions.
p(1,'number','number','Reconheça um valor numérico','Recognize a numeric value','tokens = 12\nprint(tokens)','12','tokens','"12"','Um número sem aspas pode participar de cálculos.','A number without quotes can take part in calculations.','print mostra o valor guardado, sem mostrar o nome da variável.','print displays the stored value, not the variable name.')
p(1,'string','string','Leia o nome do modelo','Read a model name','model = "local"\nprint(model)','local','model','0','Aspas delimitam texto; não fazem parte do valor mostrado.','Quotes delimit text; they are not part of the displayed value.','O conteúdo entre aspas é local.','The text between the quotes is local.')
p(1,'boolean','boolean','Um sinal de disponibilidade','An availability flag','available = True\nprint(available)','True','true','available','True e False são valores booleanos, escritos com inicial maiúscula.','True and False are Boolean values with an uppercase initial.','A variável guarda True; não é a string "true".','The variable holds True, not the string "true".')
p(1,'addition','addition','Some tokens de duas mensagens','Add tokens from two messages','prompt_tokens = 8\nanswer_tokens = 4\nprint(prompt_tokens + answer_tokens)','12','84','4','+ soma números.','+ adds numbers.','Some 8 e 4; os valores não estão entre aspas.','Add 8 and 4; the values are not quoted.',patch=('+','-','*'))
p(1,'conversion','integer-conversion','Converta a contagem recebida','Convert the received count','tokens = "12"\nprint(int(tokens) + 1)','13','121','12','int(texto) converte texto numérico em inteiro.','int(text) converts numeric text to an integer.','Converta antes de somar: o resultado de int("12") é 12.','Convert before adding: int("12") produces 12.')
p(1,'multiply','multiplication','Dois pedidos com o mesmo limite','Two requests with the same limit','limit = 6\nprint(limit * 2)','12','8','62','* multiplica números.','* multiplies numbers.','São dois grupos de seis tokens.','There are two groups of six tokens.',build=['limit = 6\n','print(limit * 2)','print(limit + 2)'])
# Unit 2: collections before max/index; no unexplained literal at the third mission.
p(2,'list','list','Reconheça a lista de modelos','Recognize the model list','models = ["fast", "local"]\nprint(models)','[\'fast\', \'local\']','fast','2','Colchetes criam uma lista ordenada de itens.','Square brackets create an ordered list of items.','print mostra a coleção inteira, incluindo os dois nomes.','print displays the whole collection, including both names.')
p(2,'zero','zero-index','A primeira posição é zero','The first position is zero','models = ["fast", "local"]\nprint(models[0])','fast','local','0','O índice 0 seleciona o primeiro elemento.','Index 0 selects the first element.','A posição zero contém fast.','Position zero contains fast.',patch=('0','1','2'))
p(2,'append','append','Cadastre um modelo local','Register a local model','models = ["fast"]\nmodels.append("local")\nprint(models)','[\'fast\', \'local\']','[\'local\']','[\'fast\']','append(item) acrescenta um item ao final da lista.','append(item) adds one item at the end of a list.','O item original continua na lista.','The original item stays in the list.')
p(2,'replace-index','list-update','Atualize uma rota na coleção','Update a route in the collection','models = ["fast", "old"]\nmodels[1] = "local"\nprint(models[1])','local','old','fast','lista[índice] = valor substitui um elemento.','list[index] = value replaces one element.','Somente a posição 1 recebe o novo texto.','Only position 1 receives the new text.',build=['models = ["fast", "old"]\n','models[1] = "local"\n','print(models[1])','print(models[0])'])
p(2,'empty','empty-list','Uma coleção sem modelos','A collection with no models','models = []\nprint(len(models))','0','1','None','[] representa uma lista vazia; len conta seus itens.','[] is an empty list; len counts its items.','Uma lista sem elementos tem comprimento zero.','A list with no elements has length zero.')
# Unit 3: preserved comparison, if and else precede these consolidations.
p(3,'equality','equality','Confirme o status exato','Check the exact status','status = 200\nprint(status == 200)','True','200','False','== compara valores, sem fazer atribuição.','== compares values without assigning them.','Os dois lados representam o mesmo número.','Both sides represent the same number.',patch=('==','!=','>'))
p(3,'and','and','Verifique duas exigências','Check two requirements','ready = True\nauthorized = False\nprint(ready and authorized)','False','True','None','and exige que as duas condições sejam verdadeiras.','and requires both conditions to be true.','A autorização está False, mesmo com ready True.','Authorization is False even though ready is True.')
p(3,'or','or','Aceite uma das rotas disponíveis','Accept either available route','remote = False\nlocal = True\nprint(remote or local)','True','False','local','or é verdadeiro quando pelo menos um lado é verdadeiro.','or is true when at least one side is true.','A rota local satisfaz uma das alternativas.','The local route satisfies one alternative.')
p(3,'not','not','Inverta o sinal de bloqueio','Invert a blocking flag','blocked = False\nprint(not blocked)','True','False','0','not inverte o valor lógico.','not reverses a Boolean value.','Inverter False produz True.','Reversing False produces True.')
p(3,'elif','elif','Três faixas de orçamento','Three budget bands','budget = 5\nif budget < 3:\n    print("local")\nelif budget < 8:\n    print("fast")\nelse:\n    print("quality")','fast','local','quality','elif testa outra condição quando o if anterior não foi atendido.','elif tests another condition when the preceding if was not met.','5 não é menor que 3, mas é menor que 8.','5 is not less than 3, but is less than 8.')
# Unit 4: isolate syntax, parameters and call sites before composite tools.
p(4,'def','def','Crie uma ferramenta sem entrada','Create a tool with no input','def ready():\n    print("ready")\nready()','ready','None','ready()','def define uma função; a chamada com () executa seu corpo.','def defines a function; calling it with () runs its body.','Definir não mostra nada; ready() chama a função.','Defining it prints nothing; ready() calls it.')
p(4,'parameter','parameter','Dê uma entrada à ferramenta','Give the tool an input','def show(model):\n    print(model)\nshow("local")','local','model','show','Um parâmetro é o nome que recebe a entrada dentro da função.','A parameter is the name that receives input inside the function.','Na chamada, "local" ocupa o lugar do parâmetro model.','In the call, "local" fills the model parameter.')
p(4,'argument','argument','Mude o argumento, preserve a função','Change the argument, keep the function','def show(model):\n    print(model)\nshow("fast")','fast','local','model','Um argumento é o valor fornecido na chamada.','An argument is the value supplied in a call.','O argumento desta chamada é "fast".','The argument in this call is "fast".',reading=('Qual valor é fornecido a show?','Which value is supplied to show?', ['"fast"','model','print'],['"fast"','model','print']))
p(4,'return','return','Use o valor retornado','Use the returned value','def cost(tokens):\n    return tokens * 2\nprint(cost(3))','6','3','None','return devolve um valor; print pode mostrá-lo depois.','return sends back a value; print can display it later.','A chamada recebe 3 e devolve 3 * 2.','The call receives 3 and returns 3 * 2.',patch=('return','print','pass'))
p(4,'default','default-parameter','Um argumento pode ter padrão','An argument can have a default','def model(name="local"):\n    return name\nprint(model())','local','None','name','Um valor padrão é usado quando o argumento é omitido.','A default is used when the argument is omitted.','A chamada não fornece name; use o padrão da definição.','The call does not supply name; use the default in the definition.')
p(4,'compose','composition','Conecte duas funções','Connect two functions','def clean(text):\n    return text\ndef prompt(text):\n    return "AI: " + clean(text)\nprint(prompt("classify"))','AI: classify','classify','AI: clean(text)','Composição usa o resultado de uma função dentro de outra.','Composition uses one function result inside another.','clean devolve classify; prompt acrescenta o prefixo.','clean returns classify; prompt adds the prefix.')
# Unit 5: text operations needed by API validation and routing.
p(5,'concat','concatenation','Construa um prefixo de prompt','Build a prompt prefix','role = "AI"\nprint(role + ": classify")','AI: classify','AIclassify',': classify','+ concatena strings, preservando espaços e sinais.','+ concatenates strings, preserving spaces and punctuation.','O segundo texto começa com dois-pontos e espaço.','The second string starts with a colon and a space.')
p(5,'strip','strip','Remova espaços da entrada','Trim input whitespace','prompt = "  classify  "\nprint(prompt.strip())','classify','  classify  ','CLASSIFY','strip() remove espaços das extremidades, não do meio.','strip() removes surrounding whitespace, not internal spaces.','Os espaços estão antes e depois do pedido.','The spaces are before and after the request.',patch=('.strip()','.upper()','.lower()'))
p(5,'lower','lower','Normalize o rótulo recebido','Normalize a received label','label = "SUPPORT"\nprint(label.lower())','support','SUPPORT','Support','lower() converte letras para minúsculas.','lower() converts letters to lowercase.','SUPPORT fica em minúsculas, sem mudar seu significado.','SUPPORT becomes lowercase without changing its meaning.')
p(5,'upper','upper','Mostre uma tag em destaque','Display an uppercase tag','tag = "api"\nprint(tag.upper())','API','api','Api','upper() converte letras para maiúsculas.','upper() converts letters to uppercase.','Todas as letras da tag passam a maiúsculas.','All letters in the tag become uppercase.',build=['tag = "api"\n','print(tag.upper())','print(tag.lower())'])
p(5,'split','split','Separe palavras de um prompt','Split prompt words','prompt = "classify this request"\nprint(prompt.split())','[\'classify\', \'this\', \'request\']','3','classifythisrequest','split() sem argumento separa texto por espaços em uma lista.','split() without an argument splits whitespace-separated text into a list.','São três palavras preservadas como itens separados.','The three words are preserved as separate items.')
p(5,'join','join','Reúna palavras normalizadas','Join normalized words','words = ["classify", "request"]\nprint(" ".join(words))','classify request','classifyrequest','[\'classify\', \'request\']','separador.join(lista) une strings usando o separador.','separator.join(list) joins strings using the separator.','O separador é um espaço entre as duas palavras.','The separator is one space between the two words.')
p(5,'text-in','membership','Procure uma intenção no texto','Find an intent in text','prompt = "please classify this"\nprint("classify" in prompt)','True','False','classify','in verifica se um elemento ou trecho está presente.','in checks whether an element or substring is present.','classify aparece dentro do pedido.','classify appears inside the request.')
p(5,'text-pipeline','text-pipeline','Limpe antes de classificar','Clean before classifying','text = "  SUPPORT  "\nlabel = text.strip().lower()\nprint(label)','support','SUPPORT','  support  ','Chamadas encadeadas transformam o resultado anterior.','Chained calls transform the previous result.','Primeiro remova espaços, depois normalize as letras.','First remove surrounding spaces, then normalize the letters.',patch=('.strip().lower()','.upper()','.lower()'))
# Unit 6: one loop feature per step, including bridges used in model evaluation.
p(6,'for','for','Visite uma lista de ferramentas','Visit a tool list','tools = ["search", "count"]\nfor tool in tools:\n    print(tool)','search\ncount','count\nsearch','[\'search\', \'count\']','for percorre itens da coleção na ordem.','for visits collection items in order.','Há uma saída por ferramenta, na mesma ordem da lista.','There is one output per tool, in list order.')
p(6,'range','range','Conte três tentativas','Count three attempts','for attempt in range(3):\n    print(attempt)','0\n1\n2','1\n2\n3','0\n1\n2\n3','range(n) produz inteiros de zero até n, sem incluir n.','range(n) produces integers from zero up to, but not including, n.','range(3) inclui 0, 1 e 2.','range(3) includes 0, 1 and 2.')
p(6,'accumulator','accumulator','Acumule o total de tokens','Accumulate total tokens','total = 0\nfor tokens in [2, 5]:\n    total = total + tokens\nprint(total)','7','5','0','Um acumulador guarda o resultado parcial entre iterações.','An accumulator keeps a partial result between iterations.','Depois de 2, acrescente 5 ao total.','After 2, add 5 to the total.',patch=('total + tokens','tokens','total'))
p(6,'while','while','Repita até o limite','Repeat until a limit','attempt = 0\nwhile attempt < 2:\n    attempt = attempt + 1\nprint(attempt)','2','1','0','while repete enquanto a condição continuar verdadeira.','while repeats while its condition remains true.','O contador chega a 2 e a condição deixa de valer.','The counter reaches 2 and the condition becomes false.')
p(6,'break','break','Pare na primeira rota local','Stop at the first local route','for model in ["local", "fast"]:\n    print(model)\n    break','local','local\nfast','fast','break encerra imediatamente o laço mais interno.','break immediately exits the innermost loop.','O primeiro item é mostrado; break impede a segunda volta.','The first item is printed; break prevents the second iteration.')
p(6,'continue','continue','Ignore um modelo indisponível','Skip an unavailable model','for model in ["offline", "local"]:\n    if model == "offline":\n        continue\n    print(model)','local','offline\nlocal','offline','continue pula o restante da iteração atual.','continue skips the rest of the current iteration.','A volta de offline é pulada; local chega ao print.','The offline iteration is skipped; local reaches print.')
p(6,'zip','zip','Emparelhe previsões e referências','Pair predictions and references','for predicted, expected in zip(["a", "b"], ["a", "c"]):\n    print(predicted == expected)','True\nFalse','True\nTrue','False\nTrue','zip emparelha coleções; nomes separados por vírgula recebem cada par.','zip pairs collections; comma-separated names receive each pair.','Compare a com a, depois b com c.','Compare a with a, then b with c.')
p(6,'enumerate','enumerate','Registre a posição de cada pedido','Record each request position','for index, task in enumerate(["chat", "search"]):\n    print(index, task)','0 chat\n1 search','1 chat\n2 search','chat 0\nsearch 1','enumerate fornece o índice e o item de cada iteração.','enumerate supplies the index and item of each iteration.','O primeiro índice é 0; print separa os argumentos por espaço.','The first index is 0; print separates arguments with a space.')
# Unit 7: structured data before API contracts.
p(7,'dict-create','dictionary','Associe modelo e nome','Associate a model key and name','response = {"model": "local"}\nprint(response["model"])','local','model','None','Dicionários associam chaves a valores; [] acessa uma chave.','Dictionaries associate keys with values; [] accesses a key.','A chave model aponta para local.','The model key points to local.')
p(7,'dict-membership','membership','Confira se uma chave existe','Check whether a key exists','response = {"model": "local"}\nprint("score" in response)','False','True','None','in em um dicionário procura nas chaves, não nos valores.','in on a dictionary searches its keys, not its values.','A única chave cadastrada é model.','The only registered key is model.')
p(7,'dict-nested','nested-access','Abra o corpo da resposta','Open the response body','response = {"data": {"model": "local"}}\nprint(response["data"]["model"])','local','data','model','Acessos encadeados atravessam dicionários aninhados.','Chained key access traverses nested dictionaries.','Primeiro entre em data; depois procure model.','First enter data; then look up model.',patch=('["data"]["model"]','["model"]','["data"]'))
p(7,'json-dumps','json-serialize','Converta dados para texto JSON','Convert data to JSON text','import json\npayload = {"model": "local"}\nprint(json.dumps(payload))','{"model": "local"}',"{'model': 'local'}",'local','json.dumps converte um objeto Python em texto JSON.','json.dumps converts a Python object to JSON text.','JSON usa aspas duplas nas chaves e nos textos.','JSON uses double quotes for keys and strings.')
p(7,'dict-items','items','Percorra chaves e valores','Visit keys and values','scores = {"fast": 8, "local": 6}\nfor name, score in scores.items():\n    print(name, score)','fast 8\nlocal 6','8 fast\n6 local','fast\nlocal','items() fornece pares de chave e valor para o laço.','items() supplies key/value pairs for a loop.','Cada par mantém o nome e o score do mesmo modelo.','Each pair keeps the name and score of the same model.')
# Unit 8: failures, recovery and tests are separate teaching steps.
p(8,'try','try-except','Proteja a leitura de um campo','Protect a field lookup','response = {}\ntry:\n    print(response["model"])\nexcept KeyError:\n    print("fallback")','fallback','model','{}','try/except permite reagir a uma exceção específica.','try/except lets code react to a specific exception.','A chave não existe; o bloco except KeyError é executado.','The key is missing; the except KeyError block runs.')
p(8,'assert','assert','Escreva uma expectativa executável','Write an executable expectation','def double(value):\n    return value * 2\nassert double(3) == 6\nprint("passed")','passed','6','AssertionError','assert verifica uma condição e falha se ela for falsa.','assert checks a condition and fails when it is false.','double(3) produz 6, então a execução continua.','double(3) produces 6, so execution continues.',patch=('== 6','== 3','== 12'))
p(8,'assert-fail','assert','Um teste também deve detectar falhas','A test must also detect failures','assert 2 + 2 == 5','','ValueError','TypeError','Um teste falho produz AssertionError e não comprova correção.','A failed test raises AssertionError and does not establish correctness.','Compare o resultado 4 com o esperado 5.','Compare the result 4 with the expected 5.',error='AssertionError')
p(8,'empty-test','edge-test','Teste a coleção vazia','Test an empty collection','def first(models):\n    if len(models) == 0:\n        return "local"\n    return models[0]\nprint(first([]))','local','IndexError','None','Um caso de borda verifica uma entrada limite, como lista vazia.','An edge case checks a boundary input such as an empty list.','A condição de comprimento zero deve vir antes do índice 0.','The zero-length condition must come before index 0.',patch=('len(models) == 0','len(models) > 0','len(models) < 0','fix'))
p(8,'negative-test','negative-test','Recuse uma entrada fora do contrato','Reject input outside a contract','def valid(score):\n    return score >= 0 and score <= 1\nprint(valid(2))','False','True','2','Um teste negativo verifica que uma entrada inválida é recusada.','A negative test checks that invalid input is rejected.','O valor 2 ultrapassa o máximo permitido de 1.','The value 2 exceeds the allowed maximum of 1.')
# Unit 9: stdlib in-memory files keep examples deterministic and offline.
p(9,'file-text','file-read','Leia um arquivo de texto em memória','Read an in-memory text file','from io import StringIO\nfile = StringIO("model=local")\nprint(file.read())','model=local','file','None','read() lê o conteúdo de um arquivo; StringIO cria um arquivo em memória.','read() reads file contents; StringIO creates an in-memory file.','O conteúdo é o texto fornecido a StringIO.','The contents are the text supplied to StringIO.')
p(9,'file-lines','file-line','Leia uma linha do log','Read one log line','from io import StringIO\nfile = StringIO("ready\ndone\n")\nprint(file.readline().strip())','ready','done','ready\ndone','readline() lê somente a próxima linha do arquivo.','readline() reads only the next file line.','A primeira linha é ready; strip retira a quebra final.','The first line is ready; strip removes the final newline.')
p(9,'file-cursor','file-cursor','Uma leitura avança o cursor','Reading advances the cursor','from io import StringIO\nfile = StringIO("local")\nfile.read()\nprint(file.read() == "")','True','False','local','O cursor avança após a leitura; no fim, read retorna texto vazio.','The cursor advances after reading; at the end, read returns an empty string.','O primeiro read já consumiu todo o texto.','The first read already consumed all the text.')
p(9,'file-seek','seek','Volte ao início para reler','Rewind before reading again','from io import StringIO\nfile = StringIO("local")\nfile.read()\nfile.seek(0)\nprint(file.read())','local','0','None','seek(0) posiciona o cursor no início do arquivo.','seek(0) positions the cursor at the file start.','O segundo read acontece depois de voltar à posição zero.','The second read happens after returning to position zero.',patch=('seek(0)','seek(5)','read()','fix'))
p(9,'with','with','Feche o recurso ao sair do bloco','Close the resource when leaving a block','from io import StringIO\nwith StringIO("local") as file:\n    data = file.read()\nprint(file.closed)','True','False','local','with gerencia a abertura e o fechamento de um recurso.','with manages opening and closing a resource.','O print está fora do bloco with.','The print is outside the with block.')
p(9,'json-file','json-load','Leia JSON de um arquivo','Read JSON from a file','import json\nfrom io import StringIO\nfile = StringIO(\'{"model":"local"}\')\nresponse = json.load(file)\nprint(response["model"])','local','model','{"model":"local"}','json.load lê de um arquivo; json.loads recebe uma string.','json.load reads from a file; json.loads receives a string.','file é o recurso que contém o texto JSON.','file is the resource containing JSON text.',patch=('json.load(file)','json.loads(file)','file.read()'))
p(9,'csv-reader','csv-reader','Leia colunas de um CSV','Read CSV columns','import csv\nfrom io import StringIO\nrows = csv.reader(StringIO("model,score\nlocal,8\n"))\nprint(list(rows)[1][0])','local','model','8','csv.reader separa linhas em colunas; list materializa o leitor.','csv.reader splits rows into columns; list materializes the reader.','A linha 0 é o cabeçalho; a linha 1 contém local e 8.','Row 0 is the header; row 1 contains local and 8.')
p(9,'csv-dict','csv-dict','Use os nomes das colunas','Use column names','import csv\nfrom io import StringIO\nrows = list(csv.DictReader(StringIO("model,score\nlocal,8\n")))\nprint(rows[0]["score"])','8','score','local','DictReader transforma cada linha em um dicionário de colunas.','DictReader turns each row into a dictionary of columns.','A primeira linha de dados tem score igual ao texto "8".','The first data row has score equal to the text "8".')
# Unit 10: responses are simulated dictionaries, never external requests.
p(10,'request','request-contract','Prepare uma requisição simulada','Prepare a simulated request','request = {"method": "POST", "body": {"prompt": "classify"}}\nprint(request["method"])','POST','GET','classify','Uma requisição descreve método e dados enviados a um serviço.','A request describes the method and data sent to a service.','Estamos lendo um dicionário; nenhuma chamada de rede acontece.','We are reading a dictionary; no network call takes place.')
p(10,'headers','headers','Reconheça um cabeçalho de formato','Recognize a format header','headers = {"Content-Type": "application/json"}\nprint(headers["Content-Type"])','application/json','Content-Type','text/plain','Content-Type descreve o formato do corpo da mensagem.','Content-Type describes the message body format.','O valor do cabeçalho identifica JSON, não o nome da chave.','The header value identifies JSON, not the key name.')
p(10,'auth-concept','authentication','Autenticação não é o conteúdo do prompt','Authentication is not prompt content','request = {"auth_required": True, "body": {"prompt": "hello"}}\nprint(request["auth_required"])','True','hello','False','Autenticação controla acesso; segredos não pertencem ao frontend público.','Authentication controls access; secrets do not belong in a public frontend.','Só há uma sinalização conceitual; nenhuma credencial é utilizada.','This is only a conceptual flag; no credential is used.')
p(10,'api-failure','service-failure','Interprete uma falha de serviço','Interpret a service failure','response = {"status": 503}\nif response["status"] != 200:\n    print("fallback")\nelse:\n    print("accepted")','fallback','accepted','503','Um status de erro deve seguir um caminho de falha explícito.','An error status should follow an explicit failure path.','503 é diferente do status de sucesso esperado, 200.','503 differs from the expected success status, 200.',patch=('!= 200','== 200','< 200','fix'))
p(10,'retry','retry-budget','Limite novas tentativas','Bound retry attempts','attempts = 3\nlimit = 3\nprint(attempts < limit)','False','True','3','Um orçamento de tentativas evita repetir uma falha indefinidamente.','A retry budget avoids repeating a failure indefinitely.','O número de tentativas já atingiu o limite.','The attempt count has already reached the limit.')
# Unit 11: deterministic behavior and explicit tool contracts.
p(11,'tool-name','tool-name','Selecione o nome permitido','Select an allowed name','tools = {"count": "count_words", "find": "search_docs"}\nprint(tools["count"])','count_words','count','search_docs','Um roteador deve mapear nomes de ferramentas de forma explícita.','A router should map tool names explicitly.','Procure o valor associado à chave count.','Look for the value associated with count.')
p(11,'tool-input','tool-input','Passe argumentos estruturados','Pass structured arguments','call = {"tool": "count", "arguments": {"text": "two words"}}\nprint(call["arguments"]["text"])','two words','count','arguments','Argumentos estruturados definem a entrada de uma ferramenta.','Structured arguments define a tool input.','Entre em arguments e leia a chave text.','Enter arguments and read the text key.')
p(11,'tool-pure','determinism','Uma ferramenta com saída previsível','A tool with predictable output','def count_words(text):\n    return len(text.split())\nprint(count_words("one two"))','2','7','1','Uma ferramenta determinística usa regras explícitas para a mesma entrada.','A deterministic tool uses explicit rules for the same input.','split cria dois itens; len conta esses itens, não caracteres.','split creates two items; len counts those items, not characters.',patch=('len(text.split())','len(text)','len([text])','fix'))
p(11,'tool-allowlist','allowlist','Recuse uma ferramenta desconhecida','Reject an unknown tool','allowed = ["count", "search"]\nrequested = "delete"\nprint(requested in allowed)','False','True','delete','Uma allowlist aceita somente nomes cadastrados.','An allowlist accepts only registered names.','delete não aparece na coleção de nomes permitidos.','delete is not in the collection of allowed names.')
p(11,'agent-state','agent-state','Um agente precisa observar um resultado','An agent needs to observe a result','state = {"tool_result": "found", "done": True}\nif state["done"]:\n    print(state["tool_result"])','found','True','tool_result','Um fluxo de agente conserva estado e observa resultados de ferramentas.','An agent workflow keeps state and observes tool results.','A flag done permite devolver o resultado já observado.','The done flag allows returning the already observed result.')
# Unit 12: distinguish counts, accuracy, latency and costs.
p(12,'accuracy','accuracy','Calcule a fração de acertos','Compute the fraction correct','correct = 3\ntotal = 4\nprint(correct / total)','0.75','0.25','3','Acurácia é acertos divididos pelo total de casos avaliados.','Accuracy is correct answers divided by total evaluated cases.','Use o total 4 como denominador.','Use the total 4 as the denominator.',patch=('correct / total','total / correct','correct / correct','fix'))
p(12,'latency','latency','Menos tempo não significa mais acertos','Less time does not mean more correct answers','latency_ms = {"fast": 20, "quality": 80}\nprint(latency_ms["fast"] < latency_ms["quality"])','True','False','0.75','Latência mede tempo; não mede qualidade da resposta.','Latency measures time, not response quality.','20 ms é menor que 80 ms, sem afirmar nada sobre acurácia.','20 ms is less than 80 ms without implying anything about accuracy.')
p(12,'cost','cost','Compare custos do mesmo lote','Compare costs for the same batch','cost = {"a": 2, "b": 5}\nprint(cost["a"] + cost["b"])','7','3','25','Custo, latência e acurácia são dimensões diferentes.','Cost, latency and accuracy are different dimensions.','Os valores são unidades fictícias para o mesmo lote.','The values are fictional units for the same batch.')
p(12,'list-comprehension','list-comprehension','Extraia rótulos de uma coleção','Extract labels from a collection','tasks = [{"expected": "a"}, {"expected": "b"}]\nexpected = [task["expected"] for task in tasks]\nprint(expected)','[\'a\', \'b\']','[\'expected\', \'expected\']','a','Uma compreensão de lista transforma cada item em um novo elemento.','A list comprehension transforms each item into a new element.','Para cada task, extraia apenas o valor de expected.','For each task, extract only its expected value.')
p(12,'small-dataset','sample-limit','Uma amostra pequena tem limites','A small sample has limits','correct = 2\ntotal = 2\nprint(correct / total)','1.0','0.5','2','Dois acertos em dois casos não provam qualidade geral do modelo.','Two correct answers out of two do not prove general model quality.','Calcule a fração observada sem extrapolar para todos os pedidos.','Compute the observed fraction without extrapolating to all requests.')
# Unit 13: interpret training evidence; no real training is invoked by lessons.
p(13,'validation-split','validation-split','Separe treino de validação','Separate training from validation','train_ids = [1, 2]\nvalidation_ids = [3]\nprint(3 in train_ids)','False','True','3','Validação deve usar exemplos separados dos usados para ajustar o modelo.','Validation should use examples separate from those used to fit the model.','O identificador 3 está na validação, não na lista de treino.','Identifier 3 is in validation, not in the training list.')
p(13,'overfit','overfitting','Duas curvas contam histórias diferentes','Two curves tell different stories','training_loss = [0.8, 0.2]\nvalidation_loss = [0.7, 0.9]\nprint(validation_loss[1] > validation_loss[0])','True','False','0.2','Treino melhorando e validação piorando podem indicar overfitting.','Improving training with worsening validation may indicate overfitting.','A perda de validação subiu de 0.7 para 0.9.','Validation loss rose from 0.7 to 0.9.')
p(13,'lambda','lambda','Defina uma função curta de seleção','Define a short selection function','validation = lambda row: row["loss"]\nprint(validation({"loss": 0.4}))','0.4','loss','None','lambda cria uma função curta que devolve uma expressão.','lambda creates a short function that returns an expression.','A expressão lê loss do dicionário recebido.','The expression reads loss from the received dictionary.')
p(13,'min-key','min-key','Selecione um checkpoint por critério','Select a checkpoint by criterion','logs = [{"epoch": 1, "loss": 0.6}, {"epoch": 2, "loss": 0.4}]\nbest = min(logs, key=lambda row: row["loss"])\nprint(best["epoch"])','2','1','0.4','key fornece o critério usado por min para comparar registros.','key supplies the criterion min uses to compare records.','O registro de menor loss tem epoch igual a 2.','The record with the lowest loss has epoch equal to 2.')
p(13,'prepared-not-running','job-state','Preparar não significa executar','Prepared does not mean running','job = {"status": "prepared", "remote_id": None}\nprint(job["status"])','prepared','running','completed','Um notebook preparado não comprova submissão ou execução no Kaggle.','A prepared notebook does not establish submission or execution on Kaggle.','O estado declarado é prepared; nenhum job é enviado neste exercício.','The declared state is prepared; this exercise submits no job.')
# Unit 14: apply already taught concepts in four small contracts before the full projects.
p(14,'mini-router','routing-practice','Consolide uma regra de roteamento','Consolidate a routing rule','def route(priority):\n    if priority == "quality":\n        return "quality_model"\n    return "local_model"\nprint(route("simple"))','local_model','quality_model','simple','Uma função pode devolver decisões diferentes conforme a entrada.','A function can return different decisions depending on input.','simple não atende à condição de quality.','simple does not meet the quality condition.',patch=('return "local_model"','return "quality_model"','return priority','fix'))
p(14,'mini-client','api-practice','Consolide o corpo de uma resposta','Consolidate a response body','import json\nresponse = {"status": 200, "body": \'{"model":"local"}\'}\nbody = json.loads(response["body"])\nprint(body.get("model", "fallback"))','local','fallback','body','O contrato separa status, texto serializado e dados Python.','The contract separates status, serialized text and Python data.','Converta body antes de procurar a chave model.','Decode body before looking up the model key.')
p(14,'mini-evaluation','evaluation-practice','Valide uma métrica completa','Validate a complete metric','predictions = ["a", "b"]\nexpected = ["a", "c"]\ncorrect = sum(p == e for p, e in zip(predictions, expected))\nprint(correct / len(expected))','0.5','1.0','2','Reutilize pares, comparações, soma e divisão para avaliar casos.','Reuse pairs, comparisons, summation and division to evaluate cases.','Somente o primeiro par corresponde; o total é dois.','Only the first pair matches; there are two cases.')
p(14,'mini-training','training-practice','Interprete o checkpoint final','Interpret a final checkpoint','logs = [{"epoch": 1, "validation_loss": 0.3}, {"epoch": 2, "validation_loss": 0.5}]\nbest = min(logs, key=lambda row: row["validation_loss"])\nprint(best["epoch"])','1','2','0.5','Selecione por validação; a última época nem sempre é a melhor.','Select by validation; the final epoch is not always best.','0.3 é a menor perda de validação observada.','0.3 is the lowest observed validation loss.')
# Explicit bridges discovered by inspecting the four complete project reference programs.
p(1,'float','float','Um score pode ter parte decimal','A score can have a fractional part','score = 0.75\nprint(score)','0.75','75','score','Um float representa um número com parte decimal.','A float represents a number with a fractional part.','O ponto separa a parte inteira da fracionária em Python.','Python uses a dot between integer and fractional parts.')
p(1,'print-pair','print-arguments','Mostre nome e contagem juntos','Show a name and count together','print("tokens", 3)','tokens 3','tokens3','3 tokens','print aceita vários argumentos e os separa por espaço por padrão.','print accepts multiple arguments and separates them with a space by default.','A ordem dos argumentos é texto, depois número.','The argument order is text, then number.')
p(2,'length','length','Conte os modelos disponíveis','Count available models','models = ["fast", "local"]\nprint(len(models))','2','1','0','len conta os elementos de uma coleção.','len counts collection elements.','Há dois nomes, independentemente do tamanho de cada texto.','There are two names, regardless of their text lengths.')
p(3,'inline-if','conditional-expression','Leia uma decisão em uma expressão','Read a decision in an expression','quality = False\nmodel = "quality" if quality else "local"\nprint(model)','local','quality','False','a if condição else b escolhe um dos dois valores.','a if condition else b chooses one of two values.','A condição False seleciona o valor depois de else.','A False condition selects the value after else.')
p(4,'unpack','unpacking','Dê nomes aos itens de um par','Name the items in a pair','name, score = ["local", 8]\nprint(name)','local','8','name','Desempacotar distribui os itens em nomes na mesma ordem.','Unpacking distributes items to names in the same order.','O primeiro item vai para name.','The first item goes to name.')
p(4,'none','none','Uma função pode não ter resultado','A function may have no result','def inspect():\n    value = 8\nprint(inspect())','None','8','value','Uma função sem return explícito devolve None.','A function without an explicit return returns None.','Guardar value dentro da função não o devolve ao chamador.','Storing value inside the function does not return it to the caller.')
p(6,'list-sum','sum','Some uma coleção de contagens','Sum a collection of counts','print(sum([2, 3, 4]))','9','3','234','sum soma os valores numéricos de uma coleção.','sum adds numeric values from a collection.','São três números a somar, não três itens a contar.','Add the three numbers; do not just count the items.')
p(7,'dict-get','get','Use um valor quando a chave faltar','Use a value when a key is missing','response = {}\nprint(response.get("model", "local"))','local','KeyError','None','get(chave, padrão) devolve o padrão quando a chave não existe.','get(key, default) returns the default when the key is missing.','O dicionário vazio não contém model.','The empty dictionary does not contain model.',patch=('.get("model", "local")','["model"]','.get("model")'))
p(7,'isinstance','isinstance','Verifique o tipo do corpo','Check the body type','body = {"model": "local"}\nprint(isinstance(body, dict))','True','False','dict','isinstance(valor, tipo) verifica se o valor tem o tipo esperado.','isinstance(value, type) checks whether a value has the expected type.','body foi criado como dicionário.','body was created as a dictionary.')
p(7,'dict-type','type-object','Valide um campo textual','Validate a text field','response = {"model": 12}\nprint(isinstance(response["model"], str))','False','True','12','str é o tipo de texto; números não são strings automaticamente.','str is the text type; numbers are not automatically strings.','O valor de model é o número 12, sem aspas.','The model value is the number 12 without quotes.')
p(8,'catch-two','exception-tuple','Trate dois tipos de falha','Handle two kinds of failure','try:\n    value = int("bad")\nexcept (ValueError, TypeError):\n    print("fallback")','fallback','ValueError','bad','Uma tupla no except permite tratar mais de um tipo de exceção.','A tuple in except allows handling more than one exception type.','int não converte bad; ValueError é um dos tipos cadastrados.','int cannot convert bad; ValueError is one of the listed types.')
p(8,'json-error','json-error','Detecte JSON malformado','Detect malformed JSON','import json\ntry:\n    json.loads("not json")\nexcept json.JSONDecodeError:\n    print("invalid")','invalid','not json','None','json.JSONDecodeError identifica texto que não é JSON válido.','json.JSONDecodeError identifies text that is not valid JSON.','not json não possui uma estrutura JSON válida.','not json has no valid JSON structure.')
p(12,'generator','generator-expression','Conte correspondências sem lista intermediária','Count matches without an intermediate list','print(sum(value > 0 for value in [2, 0, 3]))','2','3','5','Uma expressão geradora fornece valores a outra função durante a iteração.','A generator expression supplies values to another function during iteration.','As comparações produzem True, False e True; sum conta dois verdadeiros.','The comparisons yield True, False and True; sum counts two true values.')
p(12,'filtered-list','filtered-comprehension','Registre apenas os casos falhos','Record only failing cases','scores = [0, 2, 0]\nfailed = [i for i, score in enumerate(scores) if score == 0]\nprint(failed)','[0, 2]','[1]','[0, 0]','Uma condição na compreensão filtra quais itens entram na nova lista.','A condition in a comprehension filters items entering the new list.','Os scores zero estão nos índices 0 e 2.','Zero scores occur at indices 0 and 2.')
p(13,'minimum','min','Encontre a menor perda observada','Find the lowest observed loss','print(min([0.6, 0.4, 0.5]))','0.4','0.6','0.5','min devolve o menor item, sem afirmar que ele generaliza melhor.','min returns the smallest item without claiming better generalization.','Compare as três perdas numéricas registradas.','Compare the three recorded numeric losses.')
p(13,'truthiness','truthiness','Verifique se há logs para comparar','Check whether logs exist to compare','logs = []\nif not logs:\n    print("no evidence")\nelse:\n    print("select")','no evidence','select','None','Coleções vazias são falsas em condições; not inverte essa avaliação.','Empty collections are false in conditions; not reverses that evaluation.','A lista não contém registros de treinamento.','The list contains no training records.')
p(1,'recognize-value','literal-value','Antes do código: reconheça o valor','Before code: recognize a value','0.82','','Texto entre aspas','Nome de variável','Um valor literal aparece diretamente no código.','A literal value appears directly in code.','Há um número decimal, sem aspas ou nome.','There is a decimal number with no quotes or name.',reading=('O que este trecho representa?','What does this fragment represent?',['Um número decimal','Texto entre aspas','Nome de variável'],['A decimal number','Quoted text','A variable name']))
p(3,'inclusive','inclusive-comparison','Inclua o valor do limite','Include the boundary value','score = 7\nprint(score >= 7)','True','False','7','>= aceita valores maiores ou iguais ao limite.','>= accepts values greater than or equal to the boundary.','O score é exatamente igual ao limite.','The score equals the boundary.',patch=('>=','>','<','fix'))
p(6,'boolean-sum','boolean-count','Conte condições verdadeiras','Count true conditions','print(sum([True, False, True]))','2','3','1','Em uma soma, True contribui 1 e False contribui 0.','In a sum, True contributes 1 and False contributes 0.','Há duas condições verdadeiras.','There are two true conditions.')
p(7,'module-import','from-import','Importe uma função específica','Import a specific function','from json import loads\nresponse = loads(\'{"model":"local"}\')\nprint(response["model"])','local','loads','model','from módulo import nome disponibiliza um nome específico do módulo.','from module import name makes a specific module name available.','loads passa a ser chamado diretamente, sem o prefixo json.','loads can be called directly without the json prefix.')
